    return html;
}


function getSvg(comment_total,postid, blogid, pid,date) {
   let {java,cache,result} = this;
   let memoryKey = "lofter"+postid+blogid+pid;
   let Memory = String(cache.getFromMemory(memoryKey)); 
  let re = "1"+date;
  let f = Memory.includes(re);

    if (f) { 
    	java.longToast("数据加载中……请稍候");
    	let contentapi = `https://api.lofter.com/comment/pCommentList.json?postId=${postid}&blogId=${blogid}&offset=0&pid=${pid}&imgId=&commentId=`;

    	let jsonData = JSON.parse(java.ajax(contentapi)).data.list;
    	let yuan = jsonData[0].quote.replace(/^(.{40}).*/,'$1.......');
    	let content = [];
    	jsonData.forEach(x=>{
    		 let c = {
    		 	     text: x.content,
    		 	     user:x.publisherBlogInfo.blogNickName,
    		 	     time:java.timeFormat(x.publishTime),
    		 	     like:x.likeCount
    		 	}
    		 	if(x.l2Count>0){
    		 		let replyapi = `https://api.lofter.com/comment/l2/page/abtest.json?postId=${postid}&blogId=${blogid}&id=${x.id}&offset=0&fromSrc=&fromId=`;
    		 		let replyData = JSON.parse(java.ajax(replyapi)).data.list;

    		 		let replyList = [];
    		 		replyData.forEach(y=>{
    		 			let reply = {
    		 			  	text: y.content,
    		 	     user:y.publisherBlogInfo.blogNickName,
    		 	     time:java.timeFormat(y.publishTime),
    		 	     like:y.likeCount
    		 				}
    		 			replyList.push(reply)
    		 			});
    		 			c.reply = replyList
    		 		}
    		 	content.push(c)
    		});

    	let html = generateHTML(yuan,content)



java.base64Encode(html).length()>65364?java.toast("数据太大，无法加载，请减少评论数量"):
    	java.startBrowser("data:text/html;base64,"+java.base64Encode(html), "段评");

}else{
  cache.putMemory(memoryKey,"1"+date)
 }


let svg = `
  <svg width="1000" height="800" xmlns="http://www.w3.org/2000/svg">
