function applyCookieSettings() {
	  let controlUrla = getArgument('controlUrl') || controlUrl;
	  	var cookieStr = String(cookie.getCookie(controlUrla));

    var cookieData = {};
    if (cookieStr && cookieStr !== 'null' && cookieStr !== 'undefined' && cookieStr !== '') {
        var pairs = cookieStr.split('; ');
        for (var i = 0; i < pairs.length; i++) {
            var pair = pairs[i];
            var eqIndex = pair.indexOf('=');
            if (eqIndex > -1) {
                var key = pair.substring(0, eqIndex).trim();
                var value = decodeURIComponent(pair.substring(eqIndex + 1).trim());
                cookieData[key] = value;
                setArgument(key, value);
            }
        }
    }

    var displayConfig = [
        { key: 'server', label: '服务器', defaultValue: host[0] },
        { key: 'proxy', label: '访问模式', defaultValue: '云端' },
        { key: 'tab', label: '阅读模式', defaultValue: '小说' },
        { key: 'source_type', label: '阅读频道', defaultValue: '男频' },
        { key: 'sources', label: '书源选择', defaultValue: '全部' },
        { key: 'fqpara', label: '段评显示', defaultValue: 'on' },
        { key: 'disabled_sources', label: '强制搜索', defaultValue: '0' },
        { key: 'reading', label: '同步书架', defaultValue: '0' },
        { key: 'info', label: '完整简介', defaultValue: 'on' }
    ];

    var valueMap = {
        // 访问模式
        '本地': '💻 本地',
        '云端': '☁️ 云端',

        // 开关状态
        'on': '✅ 开启',
        'off': '❌ 关闭',
        '1': '✅ 开启',
        '0': '❌ 关闭',

        // 频道类型
        '男频': '👨 男频',
        '女频': '👩 女频',

        // 内容类型
        '小说': '📖 小说',
        '听书': '🎧 听书',
        '漫画': '🎨 漫画',
        '短剧': '🎬 短剧',

        // 来源类型
        'vip': '💎 VIP专属',
        'svip': '👑 SVIP专属',
        '推荐': '⭐ 网友推荐',
        '全部': '📚 全部'
    };


    var displayLines = [];

    for (var i = 0; i < displayConfig.length; i++) {
        var config = displayConfig[i];
        var value = cookieData[config.key] || config.defaultValue;

        if (!cookieData[config.key]) {
            setArgument(config.key, config.defaultValue);
        }

        var displayValue = valueMap[value] || value;
        if (config.key === 'sources' && displayValue.length > 25) {
            displayValue = displayValue.substring(0, 25) + '...';
        }

        displayLines.push(config.label + ': ' + displayValue);
    }

    // 构建提示模板
    var template = '✨ 当前配置\n';
    template += '━━━━━━━━━━━━━━━━\n';
    template += displayLines.join('\n');
    template += '\n━━━━━━━━━━━━━━━━\n';
    template += '❤️当前应用的 *⚙️书源设置* 中的配置哦❤️'

    // 显示提示
    java.longToast(template);

    return displayLines.length;
}


