// 设置保存接口
function set(num) {
    if (num < 0 || num >= data.length) {
        java.longToast("无效的接口编号！");
        return;
    }
    var show = "设置成功\n当前模式：";
    var tips = "\n‼️设置完成请点击切换模式‼️"
    var setData = JSON.parse(source.getVariable())
    setData.sz = num.toString();
    setData.tone = data[num][1];
    source.setVariable(JSON.stringify(setData, null, " "));
    var msg = show + data[num][0] + tips;
    java.longToast(msg);
}

// 设置保存接口
function set(num) {
	if (source.getVariable()=="") {
    reg(true);
}

    if (num < 0 || num >= data.length) {
        java.longToast("无效的接口编号！");
        return;
    }
    var show = "设置成功\n当前模式：";
    var tips = "\n‼️设置完成请点击切换模式‼️"
    var setData = JSON.parse(source.getVariable())

    const currentTone = data[num][1];
    if (currentTone == "tone_id=0") {
        setData.module = 2;
    } else {
        setData.module = 3;
    }

    setData.sz = num.toString();
    setData.tone = currentTone;
    source.setVariable(JSON.stringify(setData, null, "\t"));

    var currentMode = setData.module || 3;
    var msg = show + (modeNames[currentMode] || "未知模式") + 
              "\n音色设置：" + data[num][0] + tips;
    java.longToast(msg);
}


// 获取接口显示
function get() {
	if (source.getVariable()=="") {
    reg(true);
    try {
        var v = JSON.parse(source.getVariable() || "{}");
        var currentMode = v.module || 3;

        var message = "当前模式：" + (modeNames[currentMode] || "未知模式");

        if (currentMode === 2) {
            var sz = parseInt(v.sz || "0", 10);
            var toneName = (sz >= 0 && sz < data.length) ? data[sz][0] : "默认";
            message += "\n音色设置：" + toneName;
        }

        java.longToast(message);
    } catch (e) {
        java.longToast("获取模式失败：" + e.message);
    }
}else{
    try {
